using System.Windows;using System.Windows.Controls;using MessageBox=System.Windows.MessageBox;namespace DriverX.Desktop;public partial class ConnectionDialog:Window{public ConnectionProfile Profile{get;private set;}=new();public ConnectionDialog(ConnectionProfile? source=null){InitializeComponent();if(source is null)return;ProfileName.Text=source.Name;Host.Text=source.Host;Port.Text=source.Port.ToString();User.Text=source.User;Password.Password=source.Password;Keyfile.Text=source.Keyfile;RemotePath.Text=source.Path;Drive.Text=source.Drive;foreach(ComboBoxItem item in Protocol.Items)if(item.Content.ToString()==source.Protocol){Protocol.SelectedItem=item;break;}}void Cancel(object s,RoutedEventArgs e)=>DialogResult=false;void Save(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(ProfileName.Text)||string.IsNullOrWhiteSpace(Drive.Text)){MessageBox.Show("请填写名称和盘符。");return;}Profile=new(){Protocol=((ComboBoxItem)Protocol.SelectedItem).Content.ToString()!,Name=ProfileName.Text.Trim(),Host=Host.Text.Trim(),Port=int.TryParse(Port.Text,out var p)?p:22,User=User.Text.Trim(),Password=Password.Password,Keyfile=Keyfile.Text.Trim(),Path=RemotePath.Text.Trim(),Drive=Drive.Text.Trim().ToUpperInvariant()};DialogResult=true;}}
